                var u1 = (rf + 1.0 + scrollFract) / rows
                var p0 = Math.pow(u0, 2.05)
                var p1 = Math.pow(u1, 2.05)
                var y0 = horizonY + p0 * groundH
                var y1 = horizonY + p1 * groundH
